const ICON = { dev_started: '🤖', dev_done: '📬', qa_started: '🛡️', qa_accepted: '🟢', qa_rejected: '🔴', merged: '🔀', merge_failed: '⚠️', blocked: '🛑', image_pushed: '📦', deployed: '🚀', deploy_failed: '💥' };
const repo = 'https://github.com/Arvingrep/firebird-sea';
const esc = s => String(s ?? '').replace(/[<>&"]/g, c => ({ '<': '&lt;', '>': '&gt;', '&': '&amp;', '"': '&quot;' }[c]));
const safeUrl = u => /^https:\/\/github\.com\/Arvingrep\/firebird-sea\/actions\/runs\/\d+$/.test(String(u)) ? u : null;
return $input.all().map(({ json }) => {
  const e = json.body || json;
  const lines = [`${ICON[e.stage] || 'ℹ️'} <b>${esc(e.stage || 'event')}</b>`, esc(e.message)];
  if (Number.isInteger(e.issue)) lines.push(`Issue: <a href="${repo}/issues/${e.issue}">#${e.issue}</a>`);
  if (Number.isInteger(e.pr)) lines.push(`PR: <a href="${repo}/pull/${e.pr}">#${e.pr}</a>`);
  if (e.site) lines.push(`站点: ${esc(e.site)}`);
  if (e.image) lines.push(`镜像: <code>${esc(String(e.image).split(':').pop().slice(0, 12))}</code>`);
  if (safeUrl(e.run_url)) lines.push(`<a href="${e.run_url}">运行日志</a>`);
  return { json: { text: lines.join('\n') } };
});
